  $$https://randomuser.me/api/portraits/men/16.jpg$$,
  $$https://picsum.photos/seed/demo-omar-khalil-mansour/800/200$$,
  $$Omar Khalil Mansour is a livelihoods specialist with ten years of experience supporting Syrian refugees and vulnerable Jordanians to find work and grow small businesses. He currently advises UNHCR Jordan on livelihoods and economic inclusion, including work permits, home-based business registration and links to microfinance. He has led market assessments in Irbid, Mafraq and Zarqa that identified value chains with growth potential, designed SME support packages combining grants and business development services, and monitored the outcomes of cash-for-work and enterprise programmes. Omar combines market research and household surveys with close knowledge of the regulatory environment for refugee employment, and works with municipalities and the Ministry of Labour on social cohesion between refugees and host communities. He also works on economic inclusion programmes and home-based businesses run by women.$$,
  $$[{"name":"Market Research","tier":"core"},{"name":"SME Development","tier":"core"},{"name":"Refugees & Forced Displacement","tier":"core"},{"name":"Social Cohesion","tier":"strong"},{"name":"Survey Design","tier":"strong"},{"name":"Monitoring & Evaluation","tier":"strong"},{"name":"Economic Inclusion & Livelihoods","tier":"strong"},{"name":"Women's Economic Empowerment","tier":"strong"},{"name":"Migration","tier":"working"}]$$::jsonb,
  $$[{"name":"Arabic","proficiency":"fluent"},{"name":"English","proficiency":"fluent"}]$$::jsonb,
  $$[]$$::jsonb,
  $$[{"id":"58aea5cd-1d14-41e0-a05f-7160d699e698","role":"Livelihoods and Economic Inclusion Consultant","end_year":null,"logo_url":"https://cdn.brandfetch.io/unhcr.org","start_year":2021,"description":"Advises on refugee work permits, home-based businesses and access to finance.","organization":"UNHCR Jordan"},{"id":"b7f7d558-f1c0-424c-9af0-3b52db7fa762","role":"Livelihoods Program Manager","end_year":2021,"logo_url":null,"start_year":2017,"description":"Managed enterprise grants and business development services for refugees and Jordanians.","organization":"Mercy Corps Jordan"},{"id":"d3923dfc-1bef-42c8-b5b7-c4d63163637d","role":"Livelihoods Officer","end_year":2017,"logo_url":null,"start_year":2015,"description":"Ran cash-for-work and vocational training in urban host communities.","organization":"CARE International in Jordan"}]$$::jsonb,
  $$[{"id":"9a3b1943-fae0-4834-96e9-9a513a467f60","end_year":2014,"logo_url":null,"start_year":2012,"institution":"University of Jordan","degree_or_course":"MSc Economics"}]$$::jsonb,
