  $$Public Financial Management & Treasury Systems Specialist | Côte d'Ivoire & WAEMU$$,
  $$Abidjan, Côte d'Ivoire$$,
  $$senior$$,
  NULL,
  $$Ivorian citizen; contracts as an individual. Free movement within ECOWAS/WAEMU.$$,
  ARRAY[$$On-site$$, $$Hybrid$$]::text[],
  jsonb_build_object('status', 'available_from', 'from', (current_date + 20)::text, 'until', NULL),
  jsonb_build_object('status', 'available_from', 'from', (current_date + 45)::text, 'until', NULL),
  now() - interval '26 days',
  $$https://randomuser.me/api/portraits/women/21.jpg$$,
  $$https://picsum.photos/seed/demo-mariam-coulibaly-sanogo/800/200$$,
  $$Mariam Coulibaly-Sanogo is a public financial management specialist who has spent eighteen years on treasury, budget execution and tax administration systems in Côte d'Ivoire and other WAEMU countries. At the Ivorian treasury she led the team that connected budget commitment controls to the national e-procurement platform, so that contracts could only be signed once funds were reserved, and she worked with the tax administration on automatic supplier tax clearance. As a consultant for the African Development Bank she has reviewed integrated financial management information systems, designed results-based financing indicators for treasury reforms and supported the move to digital invoicing for government suppliers. She is equally at home with budget law and with the data flows between procurement, treasury and tax systems.$$,
  $$[{"name":"Public Financial Management","tier":"core"},{"name":"Tax Policy & Administration","tier":"core"},{"name":"Financial Management & Audit","tier":"core"},{"name":"Public Sector Reform","tier":"strong"},{"name":"Results-Based Financing","tier":"strong"},{"name":"Decentralization & Local Governance","tier":"strong"},{"name":"Cost-Benefit Analysis","tier":"strong"},{"name":"Technical Writing","tier":"strong"},{"name":"Official Statistics","tier":"working"},{"name":"Macroeconomic Policy","tier":"working"}]$$::jsonb,
  $$[{"name":"French","proficiency":"fluent"},{"name":"English","proficiency":"working"},{"name":"Bambara","proficiency":"working"}]$$::jsonb,
  $$[{"id":"c2a422ff-f0c2-5819-b3c5-11c2154aab01","name":"Certified Internal Auditor (CIA)","issuing_organization":"Institute of Internal Auditors","year":2012,"credential_id_or_url":null}]$$::jsonb,
  $$[{"id":"3bcaa10f-ff95-5573-bb21-09e7d7029c45","organization":"African Development Bank","role":"Public Financial Management Consultant","start_year":2020,"end_year":null,"logo_url":null,"description":"PFM and treasury systems reviews for operations in WAEMU countries."},{"id":"c600d299-0a64-5232-ad88-af749502b2a4","organization":"Direction Générale du Trésor et de la Comptabilité Publique, Côte d'Ivoire","role":"Head, Budget Execution Systems","start_year":2011,"end_year":2020,"logo_url":null,"description":"Led the treasury systems team, including the interface between commitment controls and the e-procurement platform."},{"id":"cf1ebb64-1fe0-51d9-a544-029f27526b32","organization":"Ministère de l'Économie et des Finances, Côte d'Ivoire","role":"Budget Analyst","start_year":2006,"end_year":2011,"logo_url":null,"description":"Budget preparation and execution monitoring."}]$$::jsonb,
  $$[{"id":"aa59ba43-8c79-5edb-9c7c-42418114b886","institution":"Université Félix Houphouët-Boigny","degree_or_course":"Master en Finances Publiques","start_year":2004,"end_year":2006,"logo_url":null}]$$::jsonb,
