-- Carolina Rojas Villalobos
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('5430adb6-1654-4283-afeb-c94e2133e92a', 'dd11fc10-ddf0-5f7a-8f0a-4b343644ba2e', $$Public Procurement Audit Reports, Guatemala and Honduras$$, $$Regional Transparency Programme (EU-funded)$$, NULL, 2022, 2024, $$Co-author and Analyst$$, $$Co-authored the anti-corruption and public procurement audit reports of a regional transparency programme, analysing red flags in contract data with the audit teams and drafting the findings on direct awards and contract amendments.$$, $$Reports were presented to both legislatures and led to new rules requiring publication of contract amendments.$$, $$[{"url":"https://picsum.photos/seed/demo-carolina-rojas-villalobos-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-carolina-rojas-villalobos-portfolio-1-img1/900/600","caption":"Report launch in Tegucigalpa"},{"url":"https://picsum.photos/seed/demo-carolina-rojas-villalobos-portfolio-1-img2/900/600","caption":"Editing session with the audit team"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('9e1d56db-28ff-4887-876c-d3a00ee14a18', 'dd11fc10-ddf0-5f7a-8f0a-4b343644ba2e', $$Citizen Monitoring Guide for Public Works Contracts$$, $$CoST Guatemala$$, (SELECT id FROM organizations WHERE name = $$CoST – Infrastructure Transparency Initiative$$), 2020, 2021, $$Lead Writer$$, $$Wrote the guide community committees use for citizen engagement in monitoring public works contracts, including how to read procurement documents and file information requests.$$, $$Guide used to train more than 300 community monitors.$$, $$[{"url":"https://picsum.photos/seed/demo-carolina-rojas-villalobos-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-carolina-rojas-villalobos-portfolio-2-img1/900/600","caption":"Community monitor training"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('0fcd6c2c-26a7-4b9b-ae39-8711c9addb64', 'dd11fc10-ddf0-5f7a-8f0a-4b343644ba2e', $$Regional Investment Climate Report$$, $$SIECA$$, (SELECT id FROM organizations WHERE name = $$SIECA$$), 2018, 2019, $$Editor$$, $$Edited and co-wrote a regional report on trade facilitation and investment climate reforms in Central America.$$, $$Published in Spanish and English and presented to regional economy ministers.$$, $$[{"url":"https://picsum.photos/seed/demo-carolina-rojas-villalobos-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-carolina-rojas-villalobos-portfolio-3-img1/900/600","caption":"Report cover design"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('8f87bb65-a8c0-5f65-b5c1-3c70354d85a5', 'dd11fc10-ddf0-5f7a-8f0a-4b343644ba2e', $$938d7aa4-0d4f-482c-b33d-3e9d77470244$$, NULL, $$Ricardo Solís$$, $$SIECA$$, $$Director of Economic Studies$$, $$supervisor$$, $$rsolis@sieca.int$$, (SELECT id FROM organizations WHERE name = $$SIECA$$), 2014, 2019, $$Research and editing at Programa Estado de la Nación$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I worked with Carolina at Programa Estado de la Nación, where I supervised her research and editing, before I joined SIECA. She turns technical findings into clear, accurate prose, and she understands the substance well enough to question authors. Her audit report writing for Guatemala and Honduras is excellent. I would work with her again.$$, $$auto$$, '2026-06-25T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-23T16:49:08.421Z'::timestamptz, '2026-06-25T16:34:44.421Z'::timestamptz, '2026-06-25T16:41:56.421Z'::timestamptz, '2026-06-25T16:49:08.421Z'::timestamptz, '2026-06-25T16:49:08.421Z'::timestamptz, '2026-06-26T16:49:08.421Z'::timestamptz, $$5218fdf4df606f7cdcdd8b2913ed3fcd$$, '2026-06-22T16:49:08.421Z'::timestamptz);
