-- Lucía Barrios Cifuentes
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('7cfa4bc9-d910-45b4-a6e4-1d295293ee1f', '4ed07468-e1cb-539c-a0eb-e30541fc1379', $$Integrity Assessment of Emergency Procurement, Guatemala and Honduras$$, $$Inter-American Development Bank$$, (SELECT id FROM organizations WHERE name = $$Inter-American Development Bank$$), 2021, 2022, $$Team Leader$$, $$Assessed corruption risks in COVID-19 emergency procurement in both countries, combining legal review, red-flag analysis of portal data and interviews with auditors and bidders.$$, $$Recommendations on publishing emergency contracts within 72 hours were adopted by both procurement authorities.$$, $$[{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-portfolio-1-img1/900/600","caption":"Workshop with the supreme audit institution"},{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-portfolio-1-img2/900/600","caption":"Red-flag dashboard review"}]$$::jsonb, $$[{"url":"https://example.org/ca-emergency-procurement","label":"Assessment summary"}]$$::jsonb, NULL, 1),
  ('42f6a5e0-137d-4cd7-8e4d-1f00750acd8e', '4ed07468-e1cb-539c-a0eb-e30541fc1379', $$Open Contracting Implementation Roadmap, Honduras$$, $$Open Contracting Partnership$$, (SELECT id FROM organizations WHERE name = $$Open Contracting Partnership$$), 2019, 2020, $$Lead Consultant$$, $$Prepared the roadmap for publishing HonduCompras data in the Open Contracting Data Standard and set up a civil-society monitoring pilot for road contracts.$$, $$HonduCompras began publishing OCDS data for all national-level tenders.$$, $$[{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-portfolio-2-img1/900/600","caption":"Civil-society monitoring training"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('2b1cc117-f9cc-4f0f-9acf-7a624da44f81', '4ed07468-e1cb-539c-a0eb-e30541fc1379', $$Social Audit of Municipal Public Works, Quetzaltenango$$, $$USAID$$, (SELECT id FROM organizations WHERE name = $$USAID$$), 2016, 2017, $$Citizen Engagement Advisor$$, $$Designed a social audit model in which community committees monitor municipal public works contracts and report to the auditor.$$, $$Model rolled out to 14 municipalities; committees flagged cost overruns on four contracts.$$, $$[{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-portfolio-3-img1/900/600","caption":"Community committee site visit"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('056e5315-fefb-5c39-ab6a-6efc33a28a4d', '4ed07468-e1cb-539c-a0eb-e30541fc1379', $$Indigenous Women's Leadership in Municipal Oversight, Quetzaltenango$$, $$USAID$$, (SELECT id FROM organizations WHERE name = $$USAID$$), 2018, 2019, $$Program Advisor$$, $$Designed a leadership course for indigenous women serving on municipal development councils, covering budgets, public meetings and how to request information, delivered in Spanish and K'iche'.$$, $$80 women trained; 30 now sit on municipal or community development councils.$$, $$[{"url":"https://picsum.photos/seed/demo-lucia-barrios-cifuentes-indigenous-women-s-leadership-in-municip-1/900/600","caption":"Leadership course session"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('9952d4f8-ebc5-5fe6-afac-add832c7e772', '4ed07468-e1cb-539c-a0eb-e30541fc1379', $$699fee88-a87d-4aa0-8b90-0c3b6e2c8a2e$$, NULL, $$Ana Lucía Pérez$$, $$Transparency International$$, $$Regional Coordinator, Americas$$, $$supervisor$$, $$alperez@transparency.org$$, (SELECT id FROM organizations WHERE name = $$Transparency International$$), 2007, 2012, $$Programmes at Acción Ciudadana, Guatemala$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Lucía at Acción Ciudadana, Transparency International's chapter in Guatemala, before I joined the secretariat. She ran our social audit programme and trained hundreds of citizens to monitor public works. She went on to reform procurement from inside government. She is principled and practical. I would work with her again.$$, $$auto$$, '2026-06-05T16:49:08.421Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-03T16:49:08.421Z'::timestamptz, '2026-06-05T16:34:44.421Z'::timestamptz, '2026-06-05T16:41:56.421Z'::timestamptz, '2026-06-05T16:49:08.421Z'::timestamptz, '2026-06-05T16:49:08.421Z'::timestamptz, '2026-06-06T16:49:08.421Z'::timestamptz, $$cceb9d599af0f64051cd368b6fc5f511$$, '2026-06-02T16:49:08.421Z'::timestamptz);
