INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('f8d84a6e-2eea-5e7c-ac25-8ae527a7a952', '4ed07468-e1cb-539c-a0eb-e30541fc1379', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of my years as deputy director of Guatemala's procurement directorate. I led the move to publish all contracts. What changed is that citizens and journalists could see who won public contracts and at what price.$$, 20),
  ('55879e73-0611-5114-8cc5-988ba2eb3a83', '4ed07468-e1cb-539c-a0eb-e30541fc1379', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Honduras I worked on an open contracting roadmap in a system I didn't know well. I spent my first weeks with ONCAE's data team, who showed me where the real gaps were.$$, 20),
  ('2de7f03a-3e75-5353-a732-f3e1e7e68406', '4ed07468-e1cb-539c-a0eb-e30541fc1379', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Our integrity assessment found serious weaknesses in emergency procurement. I shared the findings first with the procurement authorities, with clear recommendations, before they were published.$$, 20),
  ('2a290c34-b065-5eea-add9-b1eb9daa0c5b', '4ed07468-e1cb-539c-a0eb-e30541fc1379', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Spanish, English and K'iche'. Working with indigenous communities on social audit taught me to start with their questions, not mine.$$, 20),
  ('28b2a389-8e56-579b-aeba-aa9f54ec0e87', '4ed07468-e1cb-539c-a0eb-e30541fc1379', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in procurement integrity assessments. They are not the right tool when there is no political will to act; then building citizen demand comes first.$$, 20);
