  ('86d81fb0-c73f-5176-9e44-a635d415c66a', '4ed07468-e1cb-539c-a0eb-e30541fc1379', 'degree', $$10992640-2a72-4780-bcb9-6e67e371540d$$, $$Máster en Corrupción y Estado de Derecho, Universidad de Salamanca, 2010–2011$$, '9a363f4b', 'document_reviewed', 'document', $${"note":"Demo: certificate checked for format, dates and consistency.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-05-11T21:49:08.421Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-05-11T22:49:08.421Z'::timestamptz),
