-- Omar Khalil Mansour
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('ea259257-660d-4612-af54-d5d854a79f48', '0213e357-91f3-5088-bfa2-08dcb9538133', $$Labour Market and Value Chain Assessment, Northern Jordan$$, $$Mercy Corps$$, (SELECT id FROM organizations WHERE name = $$Mercy Corps$$), 2019, 2020, $$Assessment Lead$$, $$Led market research in Irbid, Mafraq and Zarqa covering labour demand, food processing and garment value chains, and constraints facing home-based businesses run by refugee and Jordanian women.$$, $$Identified four value chains that became the focus of a three-year enterprise programme supporting 1,800 small businesses.$$, $$[{"url":"https://picsum.photos/seed/demo-omar-khalil-mansour-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-omar-khalil-mansour-portfolio-1-img1/900/600","caption":"Interview with a home-based food producer in Irbid"},{"url":"https://picsum.photos/seed/demo-omar-khalil-mansour-portfolio-1-img2/900/600","caption":"Market mapping workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('695491e5-6426-449d-898f-353df3e0fb5a', '0213e357-91f3-5088-bfa2-08dcb9538133', $$Home-Based Business Registration Support, Jordan$$, $$UNHCR Jordan$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2022, 2024, $$Livelihoods Consultant$$, $$Worked with municipalities and the Ministry of Labour to simplify home-based business registration for refugees and monitored SME support outcomes through a household survey.$$, $$More than 2,000 refugee-run home-based businesses registered in two years.$$, $$[{"url":"https://picsum.photos/seed/demo-omar-khalil-mansour-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-omar-khalil-mansour-portfolio-2-img1/900/600","caption":"Registration help desk in Zarqa"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('222c6f81-ad45-560d-9d3b-7f7daa88fa91', '0213e357-91f3-5088-bfa2-08dcb9538133', $$Women's Home-Based Business Survey, Irbid$$, $$UNHCR$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2024, 2024, $$Livelihoods Consultant$$, $$Surveyed 600 home-based businesses run by Syrian and Jordanian women in Irbid on income, registration barriers and access to markets, and summarised options for simplified licensing.$$, $$Findings used in the municipality's licensing simplification for home-based food businesses.$$, $$[{"url":"https://picsum.photos/seed/demo-omar-khalil-mansour-women-s-home-based-business-survey-irbid-1/900/600","caption":"Interview with a home-based food producer"},{"url":"https://picsum.photos/seed/demo-omar-khalil-mansour-women-s-home-based-business-survey-irbid-2/900/600","caption":"Survey team briefing"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('c623cc06-eb8e-59c1-ba5d-3b16f2b80b7a', '0213e357-91f3-5088-bfa2-08dcb9538133', $$58aea5cd-1d14-41e0-a05f-7160d699e698$$, NULL, $$Dina Haddad$$, $$UNHCR$$, $$Senior Livelihoods Officer$$, $$supervisor$$, $$dina.haddad@unhcr.org$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2021, 2025, $$Livelihoods and economic inclusion in Jordan$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Omar has worked in my livelihoods team since 2021. He led our home-based business registration support and the market studies behind it, and he works well with ministries, municipalities and refugees alike. He is practical, reliable and well liked. I would work with him again on livelihoods and economic inclusion.$$, $$auto$$, '2026-08-14T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-14T16:34:44.421Z'::timestamptz, '2026-08-14T16:41:56.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-15T16:49:08.421Z'::timestamptz, $$8bde3066f0d67379cec4807ac4f26b48$$, '2026-08-11T16:49:08.421Z'::timestamptz);
