INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('f1e24602-f8d9-4065-9796-9d1b7a44a57c', 'c7639a01-8637-5ffc-b14d-0f6c72a0bbb3', $$Labour Market and Value Chain Assessment, Northern Jordan$$, $$UNHCR Jordan$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2018, 2019, $$Assessment Lead$$, $$Led market research in Irbid, Mafraq and Zarqa covering labour demand, food processing and garment value chains, and constraints facing home-based businesses run by refugee and Jordanian women.$$, $$Identified four value chains that became the focus of a three-year enterprise programme supporting 1,800 small businesses.$$, $$[{"url":"https://picsum.photos/seed/demo-layla-nasser-odeh-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-layla-nasser-odeh-portfolio-1-img1/900/600","caption":"Interview with a home-based food producer in Mafraq"},{"url":"https://picsum.photos/seed/demo-layla-nasser-odeh-portfolio-1-img2/900/600","caption":"Market mapping workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('a4ac3e02-1276-4f19-b929-f92b015938fc', 'c7639a01-8637-5ffc-b14d-0f6c72a0bbb3', $$Access to Finance for Refugee-Led Enterprises, Jordan$$, $$Mercy Corps$$, (SELECT id FROM organizations WHERE name = $$Mercy Corps$$), 2021, 2023, $$Programme Advisor$$, $$Worked with municipalities and microfinance institutions to open credit to refugee-run home-based businesses and monitored SME support outcomes through qualitative research.$$, $$More than 2,000 refugee-run home-based businesses accessed credit or grants in two years.$$, $$[{"url":"https://picsum.photos/seed/demo-layla-nasser-odeh-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-layla-nasser-odeh-portfolio-2-img1/900/600","caption":"Microfinance information session in Zarqa"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('abbe81f2-a517-5805-ae47-13e84392a7a8', 'c7639a01-8637-5ffc-b14d-0f6c72a0bbb3', $$Women's Home-Based Business Survey, Zarqa$$, $$Mercy Corps$$, (SELECT id FROM organizations WHERE name = $$Mercy Corps$$), 2024, 2024, $$Senior Livelihoods Advisor$$, $$Surveyed 600 home-based businesses run by Syrian and Jordanian women in Zarqa on income, registration barriers and access to markets, and summarised options for simplified licensing.$$, $$Findings used in the municipality's licensing simplification for home-based food businesses.$$, $$[{"url":"https://picsum.photos/seed/demo-layla-nasser-odeh-women-s-home-based-business-survey-zarqa-1/900/600","caption":"Interview with a home-based food producer"},{"url":"https://picsum.photos/seed/demo-layla-nasser-odeh-women-s-home-based-business-survey-zarqa-2/900/600","caption":"Survey team briefing"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('71d37d14-3eca-5deb-a327-fd42b397b126', 'c7639a01-8637-5ffc-b14d-0f6c72a0bbb3', $$3bb1e07d-cd3b-4337-a85f-c7c4ef3f8646$$, NULL, $$Samer Al-Khatib$$, $$Mercy Corps$$, $$Country Director$$, $$supervisor$$, $$samer.alkhatib@mercycorps.org$$, (SELECT id FROM organizations WHERE name = $$Mercy Corps$$), 2020, 2025, $$Livelihoods programmes in Jordan$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Layla has led livelihoods programming in my team since 2020. Her access to finance work for refugee-led enterprises was one of our most successful programmes, and she built strong partnerships with microfinance institutions. She is thoughtful and very organised. I would work with her again on livelihoods and market systems.$$, $$auto$$, '2026-08-12T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-10T16:49:08.421Z'::timestamptz, '2026-08-12T16:34:44.421Z'::timestamptz, '2026-08-12T16:41:56.421Z'::timestamptz, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-13T16:49:08.421Z'::timestamptz, $$57cbb9322a8e5e1b45dcf0e94687f03d$$, '2026-08-09T16:49:08.421Z'::timestamptz);
