-- Dilini Wickramasinghe
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('813cc034-a674-444f-b289-c857d7205e41', '3b555c66-e72e-58fb-845d-e9ce07138a70', $$National Reconciliation Barometer, Qualitative Component$$, $$UNDP Sri Lanka$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2020, 2021, $$Qualitative Research Lead$$, $$Led 60 focus groups across all provinces on trust, memory and inter-community relations to complement a national survey.$$, $$Findings framed the government's reconciliation action plan and district dialogue programmes.$$, $$[{"url":"https://picsum.photos/seed/demo-dilini-wickramasinghe-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-dilini-wickramasinghe-portfolio-1-img1/900/600","caption":"Focus group in Jaffna"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('b9f42c1a-0fb0-4ebc-b381-51e2dee65c31', '3b555c66-e72e-58fb-845d-e9ce07138a70', $$Livelihoods Recovery Evaluation for Returnee Families$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2017, 2018, $$Evaluation Team Leader$$, $$Evaluated livelihoods and housing support for displaced families returning to the Northern Province.$$, $$Evaluation led to a second phase focused on women-headed households.$$, $$[{"url":"https://picsum.photos/seed/demo-dilini-wickramasinghe-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-dilini-wickramasinghe-portfolio-2-img1/900/600","caption":"Returnee housing site visit"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('787efb2d-4718-592b-85a1-972b3deadd56', '3b555c66-e72e-58fb-845d-e9ce07138a70', $$Human Rights Commission Complaints Review$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2023, $$Lead Reviewer$$, $$Reviewed how Sri Lanka's human rights commission receives, investigates and closes complaints, and proposed a case tracking system and service standards for its regional offices.$$, $$Case tracking standards adopted by the commission in 2023.$$, $$[{"url":"https://picsum.photos/seed/demo-dilini-wickramasinghe-human-rights-commission-complaints-revie-1/900/600","caption":"Review meeting with commission staff"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('53028e38-0818-5e38-8006-d7c0faaa57b2', '3b555c66-e72e-58fb-845d-e9ce07138a70', $$Women's Political Participation in Local Councils$$, $$Centre for Poverty Analysis$$, NULL, 2013, 2014, $$Senior Researcher$$, $$Studied the 25% quota for women in local councils: how candidates were nominated, what elected women could influence, and how party structures shaped their role.$$, $$Study cited in parliamentary debates on the local authorities elections law.$$, $$[{"url":"https://picsum.photos/seed/demo-dilini-wickramasinghe-women-s-political-participation-in-local-1/900/600","caption":"Meeting with elected councillors"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('29a479ab-84d3-5882-a235-90e435b22158', '3b555c66-e72e-58fb-845d-e9ce07138a70', $$07fe901d-3dbf-4f48-b84e-4d6453904f97$$, NULL, $$Niroshan Perera$$, $$UNDP$$, $$Peace and Development Advisor$$, $$supervisor$$, $$niroshan.perera@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2004, 2008, $$Transition recovery programme in Sri Lanka$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Dilini at UNDP Sri Lanka during the transition recovery programme. She was a careful analyst and a natural listener in very tense settings. Her later work on reconciliation has been outstanding. I would work with her again on social cohesion and recovery research.$$, $$auto$$, '2026-02-25T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-02-23T16:49:08.421Z'::timestamptz, '2026-02-25T16:34:44.421Z'::timestamptz, '2026-02-25T16:41:56.421Z'::timestamptz, '2026-02-25T16:49:08.421Z'::timestamptz, '2026-02-25T16:49:08.421Z'::timestamptz, '2026-02-26T16:49:08.421Z'::timestamptz, $$b71063ee9b1e8fc07a9125bad4d16a60$$, '2026-02-22T16:49:08.421Z'::timestamptz);
