INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('87cc3efe-0908-5b16-9fe0-4f63d6df8566', '3b555c66-e72e-58fb-845d-e9ce07138a70', NULL, '813cc034-a674-444f-b289-c857d7205e41', $$Anushka Fernando$$, $$UNDP$$, $$Programme Specialist, Social Cohesion$$, $$client$$, $$anushka.fernando@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2020, 2021, $$National reconciliation barometer, qualitative component$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We commissioned Dilini to lead the qualitative component of the national reconciliation barometer. She brought together voices from all communities, with great sensitivity. Her analysis shaped our programme priorities.$$, $$auto$$, '2026-09-05T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-03T16:49:08.421Z'::timestamptz, '2026-09-05T16:34:44.421Z'::timestamptz, '2026-09-05T16:41:56.421Z'::timestamptz, '2026-09-05T16:49:08.421Z'::timestamptz, '2026-09-05T16:49:08.421Z'::timestamptz, '2026-09-06T16:49:08.421Z'::timestamptz, $$be7bde1226541b46a3ae5b2ba9c44a77$$, '2026-09-02T16:49:08.421Z'::timestamptz);
