INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('63a6d573-2b8a-5d52-8231-1265b30f08ef', '3b555c66-e72e-58fb-845d-e9ce07138a70', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the qualitative component of the national reconciliation barometer. I led it. What changed is that the government and partners could hear how people in every community actually experience reconciliation.$$, 20),
  ('811781a9-93f7-5b8b-a844-8ca737f3505e', '3b555c66-e72e-58fb-845d-e9ce07138a70', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In the Eastern Province I worked in communities I didn't know well. I relied on local researchers who spoke the language and understood the history, and I let them lead conversations.$$, 20),
  ('bc3eed88-3db8-5aac-91dc-0232d8e9a562', '3b555c66-e72e-58fb-845d-e9ce07138a70', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When our research showed that a livelihoods programme had deepened tensions between communities, I presented it carefully to the funder with practical steps to make it more conflict-sensitive.$$, 20),
  ('34508d75-3db1-5544-b407-bce933dcefbe', '3b555c66-e72e-58fb-845d-e9ce07138a70', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Sinhala, Tamil and English. In Sri Lanka, language is part of the conflict, so working in people's own language is part of doing no harm.$$, 20),
  ('8ec432b1-61f7-57a6-a530-2dcfb53a52fb', '3b555c66-e72e-58fb-845d-e9ce07138a70', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in qualitative research on social cohesion. It is not the right tool when decision-makers need to track change at scale; then a perception survey is better.$$, 20);
