-- Joseph Ssemakula
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('32848914-0308-4a2b-b2e5-675c9108c556', '9d1f06a9-7ca3-54fb-80e2-a05e454951d1', $$Refugee and Host Community Self-Reliance Programme, West Nile$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2019, 2023, $$Programme Manager$$, $$Managed a programme supporting agricultural livelihoods and savings groups for refugees and host communities in four settlements, with peace committees to resolve land disputes.$$, $$Reached 24,000 households; land disputes reported to peace committees resolved in 80% of cases.$$, $$[{"url":"https://picsum.photos/seed/demo-joseph-ssemakula-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-joseph-ssemakula-portfolio-1-img1/900/600","caption":"Savings group meeting in Bidibidi"},{"url":"https://picsum.photos/seed/demo-joseph-ssemakula-portfolio-1-img2/900/600","caption":"Peace committee session"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('1b592f82-2083-46a5-aad6-f02c1dbe7717', '9d1f06a9-7ca3-54fb-80e2-a05e454951d1', $$Emergency Food Assistance, Upper Nile$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2014, 2017, $$Programme Manager$$, $$Managed general food distributions and nutrition support for displaced populations in Upper Nile State.$$, $$Maintained distributions to 120,000 people through two rainy seasons.$$, $$[{"url":"https://picsum.photos/seed/demo-joseph-ssemakula-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-joseph-ssemakula-portfolio-2-img1/900/600","caption":"Food distribution site"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('84cfefa4-ac31-56d3-90f0-c8aad04d0283', '9d1f06a9-7ca3-54fb-80e2-a05e454951d1', $$Settlement Shelter Upgrade, Rhino Camp$$, $$Danish Refugee Council$$, (SELECT id FROM organizations WHERE name = $$Danish Refugee Council$$), 2021, 2022, $$Area Manager$$, $$Managed the upgrade of 1,500 emergency shelters to durable mud-brick houses in Rhino Camp, with cash grants for materials, local mason training and community monitoring.$$, $$1,500 households in durable shelters; 120 masons trained, half of them women.$$, $$[{"url":"https://picsum.photos/seed/demo-joseph-ssemakula-settlement-shelter-upgrade-rhino-camp-1/900/600","caption":"Mud-brick house construction"},{"url":"https://picsum.photos/seed/demo-joseph-ssemakula-settlement-shelter-upgrade-rhino-camp-2/900/600","caption":"Mason training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('e62c2ee2-d383-564a-9f01-80cbd72e6825', '9d1f06a9-7ca3-54fb-80e2-a05e454951d1', $$c0ac4af2-a2f8-4aea-9050-d1ce53721c21$$, NULL, $$Charlotte Nielsen$$, $$Danish Refugee Council$$, $$Country Director$$, $$supervisor$$, $$charlotte.nielsen@drc.ngo$$, (SELECT id FROM organizations WHERE name = $$Danish Refugee Council$$), 2018, 2025, $$Refugee response in West Nile$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Joseph has managed our West Nile area office since 2018. He leads large teams in difficult conditions with fairness and calm, and his grant management is impeccable. Refugee and host community leaders trust him. I would work with him again on any refugee response programme.$$, $$auto$$, '2026-07-15T16:49:08.421Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-13T16:49:08.421Z'::timestamptz, '2026-07-15T16:34:44.421Z'::timestamptz, '2026-07-15T16:41:56.421Z'::timestamptz, '2026-07-15T16:49:08.421Z'::timestamptz, '2026-07-15T16:49:08.421Z'::timestamptz, '2026-07-16T16:49:08.421Z'::timestamptz, $$71bd2172d350034e0e5b3e531e35f4f0$$, '2026-07-12T16:49:08.421Z'::timestamptz);
