-- Rania Haddad
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('54e22102-b536-4660-a392-7bf55d3857ee', 'ad4ddda8-3134-5870-b692-df168b1e2488', $$Social Cohesion Assessment, North Lebanon and Bekaa$$, $$UNDP Lebanon$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2023, 2024, $$Research Lead$$, $$Designed a mixed-methods assessment of tension between refugee and host communities in 12 municipalities, with a 1,200-household survey and 40 focus groups.$$, $$Findings reshaped municipal service projects toward shared water and waste services; tension scores fell in follow-up monitoring.$$, $$[{"url":"https://picsum.photos/seed/demo-rania-haddad-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rania-haddad-portfolio-1-img1/900/600","caption":"Focus group with host community youth in Akkar"},{"url":"https://picsum.photos/seed/demo-rania-haddad-portfolio-1-img2/900/600","caption":"Municipal dialogue session in Zahle"}]$$::jsonb, $$[{"url":"https://example.org/lebanon-social-cohesion-2024","label":"Assessment brief"}]$$::jsonb, NULL, 1),
  ('dc606e09-ed28-4152-861a-a3d013fef3c5', 'ad4ddda8-3134-5870-b692-df168b1e2488', $$Conflict-Sensitivity Review of a Livelihoods Programme, Jordan$$, $$Danish Refugee Council$$, (SELECT id FROM organizations WHERE name = $$Danish Refugee Council$$), 2021, 2022, $$Conflict Sensitivity Advisor$$, $$Reviewed targeting and grant criteria of a refugee livelihoods programme for unintended effects on host-community relations.$$, $$Targeting rules revised to include vulnerable Jordanian households; complaints about unfairness dropped.$$, $$[{"url":"https://picsum.photos/seed/demo-rania-haddad-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rania-haddad-portfolio-2-img1/900/600","caption":"Key informant interview in Mafraq"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('3c5dba97-4b8a-55a2-af10-fd3152e87def', 'ad4ddda8-3134-5870-b692-df168b1e2488', $$Media Narratives on Refugees, Lebanon$$, $$UNESCO$$, (SELECT id FROM organizations WHERE name = $$UNESCO$$), 2022, 2022, $$Lead Researcher$$, $$Analysed coverage of refugees in Lebanese television and online media over a year and ran workshops with journalists on conflict-sensitive reporting.$$, $$Guidelines adopted by two broadcasters.$$, $$[{"url":"https://picsum.photos/seed/demo-rania-haddad-media-narratives-on-refugees-lebanon-1/900/600","caption":"Journalist workshop in Beirut"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('59e1245b-5fc5-5844-9b8a-4935bbf7a643', 'ad4ddda8-3134-5870-b692-df168b1e2488', $$Conflict Sensitivity Training for Municipal Staff$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2018, 2019, $$Trainer$$, $$Designed and delivered conflict sensitivity training for municipal staff in 20 municipalities hosting refugees, with follow-up coaching on service planning.$$, $$20 municipalities trained; 12 revised their service plans.$$, $$[{"url":"https://picsum.photos/seed/demo-rania-haddad-conflict-sensitivity-training-for-munici-1/900/600","caption":"Training session in Zahle"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('a4ee46ce-285c-59c9-8d1f-8b3ae3adbbec', 'ad4ddda8-3134-5870-b692-df168b1e2488', $$4d52b833-9e86-4698-93b7-6512a9453e20$$, NULL, $$Georges Abi Nader$$, $$UNDP$$, $$Social Stability Programme Manager$$, $$supervisor$$, $$georges.abinader@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2013, 2017, $$Social stability analysis in Lebanon$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Rania was a social stability analyst in my programme for four years. Her conflict analysis helped us decide where to work and how, and municipalities trusted her. She is rigorous, brave and fair. I would work with her again on social cohesion research.$$, $$auto$$, '2026-07-30T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-28T16:49:08.421Z'::timestamptz, '2026-07-30T16:34:44.421Z'::timestamptz, '2026-07-30T16:41:56.421Z'::timestamptz, '2026-07-30T16:49:08.421Z'::timestamptz, '2026-07-30T16:49:08.421Z'::timestamptz, '2026-07-31T16:49:08.421Z'::timestamptz, $$949aa712cba59ffe212e8c0a91680fc7$$, '2026-07-27T16:49:08.421Z'::timestamptz);
