INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('907ed789-3a35-54c0-8f2f-34c76dfd9c38', 'ad4ddda8-3134-5870-b692-df168b1e2488', $$b17b7c38-288c-48fa-874d-4f8150a85274$$, NULL, $$Dr. Leila Mansour$$, $$International Rescue Committee$$, $$Director of Research$$, $$supervisor$$, $$leila.mansour@rescue.org$$, (SELECT id FROM organizations WHERE name = $$International Rescue Committee$$), 2009, 2013, $$Research on refugee protection and services$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Rania as a research officer at the IRC. She led qualitative studies with refugees with real care and produced findings our programmes used. I have followed her career since, and she has become one of the leading social cohesion researchers in the region.$$, $$auto$$, '2026-02-15T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-02-13T16:49:08.421Z'::timestamptz, '2026-02-15T16:34:44.421Z'::timestamptz, '2026-02-15T16:41:56.421Z'::timestamptz, '2026-02-15T16:49:08.421Z'::timestamptz, '2026-02-15T16:49:08.421Z'::timestamptz, '2026-02-16T16:49:08.421Z'::timestamptz, $$de304f952124ee218f371695118496d1$$, '2026-02-12T16:49:08.421Z'::timestamptz);
