INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('2011efff-ce10-548f-9cb2-d6edb79f190e', 'ad4ddda8-3134-5870-b692-df168b1e2488', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the social cohesion assessment in North Lebanon and the Bekaa. I led it. What changed is that UNDP and municipalities targeted their support to the places where tensions were rising, before violence broke out.$$, 20),
  ('cc6b58f5-0252-53f9-bb13-122bcd71aa8a', 'ad4ddda8-3134-5870-b692-df168b1e2488', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Jordan I reviewed a livelihoods programme in communities I didn't know. I spent time with local staff first to understand relationships between refugees and hosts before designing interviews.$$, 20),
  ('67075d47-bbb5-5a40-84ef-47b24c7787e5', 'ad4ddda8-3134-5870-b692-df168b1e2488', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When our review found that a programme was creating tension, I explained it to the funder with evidence and simple changes, so it became an improvement plan rather than a criticism.$$, 20),
  ('04e39b72-a12d-58c3-99bd-559d8d173d3a', 'ad4ddda8-3134-5870-b692-df168b1e2488', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Arabic, English and French. Working with local partners is essential in Lebanon: they know which questions can be asked and which cannot.$$, 20),
  ('51829e26-62a1-5ccb-9fa1-5e0d6c2d47ed', 'ad4ddda8-3134-5870-b692-df168b1e2488', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in conflict analysis and social cohesion assessments. They are not the right tool for measuring programme impact; that needs a proper evaluation design.$$, 20);
