  ('14334aa8-3bf1-526e-bc9f-3735be988b90', 'ad4ddda8-3134-5870-b692-df168b1e2488', 'degree', $$92ac5034-b07c-4013-aa9d-eae7ddf4234c$$, $$MA Conflict, Security and Development, University of Sussex, 2011–2012$$, '37719556', 'document_reviewed', 'document', $${"note":"Demo: certificate checked for format, dates and consistency.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-01-21T21:49:08.421Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-01-21T22:49:08.421Z'::timestamptz),
