-- Joaquin Reyes Manalo
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('13cbd3be-4363-4297-8e55-7c7587ded152', '1ab138f0-db40-596d-b6be-72a6ec048f58', $$Agricultural Credit Guarantee Design, Philippines$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2021, 2023, $$Financial Modeling Lead$$, $$Built the financial model for a partial credit guarantee for agricultural loans, testing claim rates, pricing and fiscal exposure.$$, $$Guarantee approved as part of an ADB policy-based loan; 14 rural banks enrolled in year one.$$, $$[{"url":"https://picsum.photos/seed/demo-joaquin-reyes-manalo-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-joaquin-reyes-manalo-portfolio-1-img1/900/600","caption":"Model review session with the guarantee agency"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('3996ffad-5851-4fd9-b460-07be513edc69', '1ab138f0-db40-596d-b6be-72a6ec048f58', $$Digital Payments for Farmers Diagnostic, Indonesia$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2020, 2021, $$Financial Inclusion Specialist$$, $$Assessed use of digital financial services by farmer groups and the regulatory barriers for agent networks in rural areas.$$, $$Diagnostic informed the digital finance component of a rural development project.$$, $$[{"url":"https://picsum.photos/seed/demo-joaquin-reyes-manalo-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-joaquin-reyes-manalo-portfolio-2-img1/900/600","caption":"Agent banking outlet in East Java"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('7dd66f50-6085-52a7-8c6f-73adc4fcf16d', '1ab138f0-db40-596d-b6be-72a6ec048f58', $$Credit Information System Reform, Philippines$$, $$Bangko Sentral ng Pilipinas$$, (SELECT id FROM organizations WHERE name = $$Bangko Sentral ng Pilipinas$$), 2016, 2018, $$Financial Inclusion Specialist$$, $$Supported the central bank and the national credit information corporation to bring rural banks and microfinance institutions into the credit reporting system, including data standards and consent rules.$$, $$Over 400 rural banks and MFIs submitting data by 2019.$$, $$[{"url":"https://picsum.photos/seed/demo-joaquin-reyes-manalo-credit-information-system-reform-philipp-1/900/600","caption":"Data standards workshop with rural banks"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('7641d8d3-5f6c-5d8b-bbcc-cf36ba24f030', '1ab138f0-db40-596d-b6be-72a6ec048f58', $$Microinsurance Regulation Review$$, $$Bangko Sentral ng Pilipinas$$, (SELECT id FROM organizations WHERE name = $$Bangko Sentral ng Pilipinas$$), 2014, 2015, $$Financial Inclusion Specialist$$, $$Reviewed the rules for microinsurance products sold through banks and MFIs, with consumer protection and claims settlement standards.$$, $$Revised circular issued; average claims settlement time fell to ten days.$$, $$[{"url":"https://picsum.photos/seed/demo-joaquin-reyes-manalo-microinsurance-regulation-review-1/900/600","caption":"Consultation with microinsurers"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('093258f8-f24a-5080-a583-8ddbd4d7729b', '1ab138f0-db40-596d-b6be-72a6ec048f58', $$7686e723-30db-4bde-afe8-eff94af9e31b$$, NULL, $$Dr. Arjun Bose$$, $$Asian Development Bank$$, $$Principal Financial Sector Specialist$$, $$supervisor$$, $$abose@adb.org$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2019, 2025, $$Rural finance operations in Southeast Asia$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Joaquin has been our rural finance consultant since 2019. His agricultural credit guarantee design for the Philippines is now an ADB operation, and his diagnostic of digital payments for farmers in Indonesia was excellent. He combines policy knowledge from the central bank with strong modelling. I would work with him again.$$, $$auto$$, '2026-08-29T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-27T16:49:08.421Z'::timestamptz, '2026-08-29T16:34:44.421Z'::timestamptz, '2026-08-29T16:41:56.421Z'::timestamptz, '2026-08-29T16:49:08.421Z'::timestamptz, '2026-08-29T16:49:08.421Z'::timestamptz, '2026-08-30T16:49:08.421Z'::timestamptz, $$87dc615a86c1a48bcf634dc9618465c7$$, '2026-08-26T16:49:08.421Z'::timestamptz);
