INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('60ca288f-718a-59e6-8721-f11535e5cf2b', '1ab138f0-db40-596d-b6be-72a6ec048f58', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the agricultural credit guarantee design in the Philippines. I led the financial modelling and consultations. What changed is that rural banks began lending to smallholders they had considered too risky.$$, 20),
  ('76ac627e-2ef0-51ec-81a9-9c9d080e2bef', '1ab138f0-db40-596d-b6be-72a6ec048f58', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Indonesia I worked on digital payments for farmers in a system new to me. I spent time with village agents and farmers' groups first, to understand how cash actually moved.$$, 20),
  ('439e0d1e-7ce6-56e1-9e2c-5241f45fccd2', '1ab138f0-db40-596d-b6be-72a6ec048f58', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When our model showed that a proposed guarantee fee was too low to be sustainable, I presented the numbers and two alternatives to the government, and we agreed on a phased fee.$$, 20),
  ('888434d8-523b-5f89-a67a-4a6b0446e470', '1ab138f0-db40-596d-b6be-72a6ec048f58', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Filipino and English, and across Southeast Asia I rely on local partners. Rural bank managers know their borrowers better than any dataset.$$, 20),
  ('7499e60a-81ef-5145-844f-f6cc77aa81e3', '1ab138f0-db40-596d-b6be-72a6ec048f58', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in financial modelling of credit guarantees. It is not the right tool when lenders lack basic capacity; then technical assistance comes before guarantees.$$, 20);
