-- Siti Rahmawati Nugroho
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('b4e6effe-41df-42e9-bec5-31251575739a', 'c68b0449-f6f5-532f-9f24-78544ef1aff6', $$Coffee and Cocoa Value-Chain Finance Study, Sulawesi and East Java$$, $$IFAD$$, (SELECT id FROM organizations WHERE name = $$IFAD$$), 2021, 2022, $$Lead Consultant$$, $$Led market research on financing gaps across coffee and cocoa value chains, with a survey of 800 farm households and interviews with off-takers and lenders.$$, $$Study led to a value-chain finance window in IFAD's rural development programme reaching 6,000 farmers.$$, $$[{"url":"https://picsum.photos/seed/demo-siti-rahmawati-nugroho-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-siti-rahmawati-nugroho-portfolio-1-img1/900/600","caption":"Cocoa farmer interview in Sulawesi"},{"url":"https://picsum.photos/seed/demo-siti-rahmawati-nugroho-portfolio-1-img2/900/600","caption":"Off-taker warehouse visit"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('df5eb4e5-96bd-42dd-9e1d-9ec7ad2d4ae1', 'c68b0449-f6f5-532f-9f24-78544ef1aff6', $$Maize Value Chain Development Project Design$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2016, 2018, $$Project Officer$$, $$Prepared the agribusiness and finance components of a maize value chain project, including financial modeling of contract farming arrangements.$$, $$Project approved with a $120 million financing package.$$, $$[{"url":"https://picsum.photos/seed/demo-siti-rahmawati-nugroho-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-siti-rahmawati-nugroho-portfolio-2-img1/900/600","caption":"Maize aggregation centre"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('ade62ed6-d488-5a3a-9395-8fb0c37a4542', 'c68b0449-f6f5-532f-9f24-78544ef1aff6', $$Extension Services Review for Smallholder Cocoa, Sulawesi$$, $$IFAD$$, (SELECT id FROM organizations WHERE name = $$IFAD$$), 2023, 2023, $$Agribusiness Specialist$$, $$Reviewed public and company extension services for smallholder cocoa farmers in Sulawesi, including women's access to training and inputs, and proposed a joint extension model.$$, $$Joint extension model piloted with two cocoa buyers in 30 villages.$$, $$[{"url":"https://picsum.photos/seed/demo-siti-rahmawati-nugroho-extension-services-review-for-smallholde-1/900/600","caption":"Cocoa farmer training"},{"url":"https://picsum.photos/seed/demo-siti-rahmawati-nugroho-extension-services-review-for-smallholde-2/900/600","caption":"Women farmers' group discussion"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('da4d17ce-7884-5f03-babc-8fa5a36fe1f8', 'c68b0449-f6f5-532f-9f24-78544ef1aff6', $$209bea35-04aa-48bc-aded-fbd1e0b45c91$$, NULL, $$Dr. Wahyu Hidayat$$, $$Asian Development Bank$$, $$Principal Natural Resources and Agriculture Specialist$$, $$supervisor$$, $$whidayat@adb.org$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2012, 2019, $$Agriculture and rural development projects in Indonesia$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Siti for seven years at ADB, where she designed and managed agriculture and rural development projects. Her maize value chain project design was one of our best. She understands farmers, banks and government equally well. I would work with her again on agribusiness and rural finance.$$, $$auto$$, '2026-07-05T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-03T16:49:08.421Z'::timestamptz, '2026-07-05T16:34:44.421Z'::timestamptz, '2026-07-05T16:41:56.421Z'::timestamptz, '2026-07-05T16:49:08.421Z'::timestamptz, '2026-07-05T16:49:08.421Z'::timestamptz, '2026-07-06T16:49:08.421Z'::timestamptz, $$7f1ba7a80835af4f7fae32e4905d487c$$, '2026-07-02T16:49:08.421Z'::timestamptz);
