INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('a9554ed4-8afc-4fd2-b911-67475734d6c8', '9323ce82-5adf-5dbf-bbb4-cd2f7d37cf83', $$Smallholder Credit Demand Survey, Nusa Tenggara$$, $$MicroSave Consulting$$, (SELECT id FROM organizations WHERE name = $$MicroSave Consulting$$), 2023, 2024, $$Market Research Analyst$$, $$Designed and analysed a demand-side survey of 900 farm households in maize and seaweed value chains, with interviews of rural banks and cooperatives on lending practices.$$, $$Survey identified an unmet seasonal credit need and led two partner institutions to pilot harvest-linked repayment schedules.$$, $$[{"url":"https://picsum.photos/seed/demo-rizky-pratama-wibowo-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rizky-pratama-wibowo-portfolio-1-img1/900/600","caption":"Survey enumeration in a seaweed farming village"},{"url":"https://picsum.photos/seed/demo-rizky-pratama-wibowo-portfolio-1-img2/900/600","caption":"Interview with a cooperative manager"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('902c579b-4d66-47ab-8822-503b5fb8801b', '9323ce82-5adf-5dbf-bbb4-cd2f7d37cf83', $$Women Farmers' Access to Credit, Mindanao$$, $$MicroSave Consulting$$, (SELECT id FROM organizations WHERE name = $$MicroSave Consulting$$), 2021, 2022, $$Research Analyst$$, $$Combined survey data and focus groups to analyse barriers to credit faced by women coffee farmers and women-led agri-enterprises.$$, $$Recommendations on collateral alternatives were adopted in a partner bank's lending policy.$$, $$[{"url":"https://picsum.photos/seed/demo-rizky-pratama-wibowo-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rizky-pratama-wibowo-portfolio-2-img1/900/600","caption":"Focus group with women coffee farmers"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('a97da0ec-6330-5943-8a33-03f8fddd6a30', '9323ce82-5adf-5dbf-bbb4-cd2f7d37cf83', $$Crop Insurance Uptake Survey, East Java$$, $$MicroSave Consulting$$, (SELECT id FROM organizations WHERE name = $$MicroSave Consulting$$), 2024, 2025, $$Senior Analyst$$, $$Surveyed 900 rice and maize farmers on their awareness and use of the government-subsidised crop insurance scheme, tested two message designs for enrolment, and charted uptake by gender and farm size.$$, $$Simplified enrolment message adopted by the provincial agriculture office; uptake rose by 7 points in pilot villages.$$, $$[{"url":"https://picsum.photos/seed/demo-rizky-pratama-wibowo-crop-insurance-uptake-survey-east-java-1/900/600","caption":"Farmer interviews in Jember"},{"url":"https://picsum.photos/seed/demo-rizky-pratama-wibowo-crop-insurance-uptake-survey-east-java-2/900/600","caption":"Uptake charts"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
