-- Nguyễn Thu Hà
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('15942b8e-4461-4d83-b812-d79c0160afc6', '890c205e-4c05-509e-95e3-5bef6e708547', $$Credit Needs Assessment for Coffee Cooperatives, Central Highlands$$, $$IFAD$$, (SELECT id FROM organizations WHERE name = $$IFAD$$), 2021, 2022, $$Lead Researcher$$, $$Ran market research with 600 coffee-farming households and 12 cooperatives on seasonal credit needs, and built a financial modeling tool for lenders to price harvest-linked loans.$$, $$Two agricultural lenders adopted the pricing tool; cooperative members received seasonal credit for the first time.$$, $$[{"url":"https://picsum.photos/seed/demo-nguyen-thu-ha-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-nguyen-thu-ha-portfolio-1-img1/900/600","caption":"Cooperative meeting in Dak Lak"},{"url":"https://picsum.photos/seed/demo-nguyen-thu-ha-portfolio-1-img2/900/600","caption":"Loan pricing tool training"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('3eb3a6a8-e104-4142-bff6-13f5b8573aac', '890c205e-4c05-509e-95e3-5bef6e708547', $$Supplier Finance for Seaweed Farmers, Philippines and Indonesia$$, $$Impact investor consortium$$, NULL, 2023, 2024, $$Value Chain Advisor$$, $$Designed supplier finance schemes through which seaweed processors advance inputs to farmers, with financial modeling of processor cash flow and farmer repayment, to expand financial inclusion in coastal communities.$$, $$Scheme launched with two processors serving 1,400 seaweed farmers.$$, $$[{"url":"https://picsum.photos/seed/demo-nguyen-thu-ha-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-nguyen-thu-ha-portfolio-2-img1/900/600","caption":"Seaweed drying in Palawan"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('bfece9c6-c453-5324-8f51-62579abe730b', '890c205e-4c05-509e-95e3-5bef6e708547', $$Cooperative Business Plans for Rice Farmers, Mekong Delta$$, $$SNV$$, (SELECT id FROM organizations WHERE name = $$SNV$$), 2018, 2019, $$Agriculture Advisor$$, $$Helped twelve rice cooperatives in the Mekong Delta prepare business plans with costs, margins and financing needs for drying and milling equipment, and linked them with local banks and buyers.$$, $$Eight cooperatives secured loans; average price received by members rose by 9%.$$, $$[{"url":"https://picsum.photos/seed/demo-nguyen-thu-ha-cooperative-business-plans-for-rice-farm-1/900/600","caption":"Cooperative planning session"},{"url":"https://picsum.photos/seed/demo-nguyen-thu-ha-cooperative-business-plans-for-rice-farm-2/900/600","caption":"Rice drying facility"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('4cae14e4-b61d-5264-a02d-bf748d0d5a27', '890c205e-4c05-509e-95e3-5bef6e708547', $$2f34af6c-77d6-4cc5-9433-7f588091562b$$, NULL, $$Pham Van Duc$$, $$SNV$$, $$Agriculture Sector Leader$$, $$supervisor$$, $$duc.pham@snv.org$$, (SELECT id FROM organizations WHERE name = $$SNV$$), 2015, 2020, $$Agriculture programmes in Vietnam$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Thu Hà was an agriculture advisor in my team for five years. She worked with coffee and rice cooperatives on business planning and finance, and she always made sure women members had a voice. She is practical and well organised. I would work with her again on agribusiness and value chain work.$$, $$auto$$, '2026-07-20T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-18T16:49:08.421Z'::timestamptz, '2026-07-20T16:34:44.421Z'::timestamptz, '2026-07-20T16:41:56.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-21T16:49:08.421Z'::timestamptz, $$21737ea15cc10a8e338b7aefd69d9461$$, '2026-07-17T16:49:08.421Z'::timestamptz);
