-- Neema Mwakyusa
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('9c29db0a-c7b4-4a62-8dd9-3afda262982b', '35d63c36-07b5-5f22-9a9e-d8e994374d5a', $$Merchant Credit Scoring Prototype$$, $$Fintech start-up (Dar es Salaam)$$, NULL, 2023, 2024, $$Data Analyst$$, $$Built a credit scoring prototype for small merchants from mobile money transaction histories using Python.$$, $$Prototype supported a pilot of working-capital loans to 300 merchants.$$, $$[{"url":"https://picsum.photos/seed/demo-neema-mwakyusa-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-neema-mwakyusa-portfolio-1-img1/900/600","caption":"Credit scoring dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('1814f863-2e3d-4711-93ff-10d6cb529764', '35d63c36-07b5-5f22-9a9e-d8e994374d5a', $$Urban SME Savings and Mobile Wallet Study$$, $$Financial Sector Deepening Tanzania$$, (SELECT id FROM organizations WHERE name = $$Financial Sector Deepening Tanzania$$), 2021, 2022, $$Research Assistant$$, $$Supported market research on how urban SMEs use savings groups and mobile wallets in Dar es Salaam and Mwanza.$$, $$Findings presented to the central bank fintech working group.$$, $$[{"url":"https://picsum.photos/seed/demo-neema-mwakyusa-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-neema-mwakyusa-portfolio-2-img1/900/600","caption":"Interview with a market trader in Mwanza"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('4407f80d-fcfa-5fc5-90f9-1dcb783758c9', '35d63c36-07b5-5f22-9a9e-d8e994374d5a', $$Fraud Detection Rules for Mobile Wallet Transactions$$, $$Fintech start-up (Dar es Salaam)$$, NULL, 2024, 2025, $$Data Analyst$$, $$Developed and tested rules to flag suspicious mobile wallet transactions, with a dashboard for the operations team and monthly reviews of false positives.$$, $$Fraud losses fell by 40% while false alarms stayed under 2%.$$, $$[{"url":"https://picsum.photos/seed/demo-neema-mwakyusa-fraud-detection-rules-for-mobile-wallet--1/900/600","caption":"Fraud dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('d6c73e54-a863-545c-8dcd-7e2f3f8e21a0', '35d63c36-07b5-5f22-9a9e-d8e994374d5a', $$c3d213f3-658b-451d-a77d-e5059db80fdf$$, NULL, $$Grace Mushi$$, $$Financial Sector Deepening Tanzania$$, $$Head of Research$$, $$supervisor$$, $$grace.mushi@fsdt.or.tz$$, (SELECT id FROM organizations WHERE name = $$Financial Sector Deepening Tanzania$$), 2021, 2022, $$Research internship on urban SME savings$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Neema was a research intern in my team. She analysed mobile wallet data for our urban SME savings study and did it carefully and quickly. She asks good questions and learns fast. I would work with her again on financial inclusion data.$$, $$auto$$, '2026-06-05T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-03T16:49:08.421Z'::timestamptz, '2026-06-05T16:34:44.421Z'::timestamptz, '2026-06-05T16:41:56.421Z'::timestamptz, '2026-06-05T16:49:08.421Z'::timestamptz, '2026-06-05T16:49:08.421Z'::timestamptz, '2026-06-06T16:49:08.421Z'::timestamptz, $$b49cbfc404300b459c58e514bf34dba0$$, '2026-06-02T16:49:08.421Z'::timestamptz);
