-- Rowena Bautista Lacson
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('9778935f-f548-4e6a-b96b-5090b693118a', '57e08d91-59a0-59d4-b146-bbd1d987a615', $$Value-Chain Finance Products for Coconut and Coffee, Mindanao$$, $$IFAD$$, (SELECT id FROM organizations WHERE name = $$IFAD$$), 2022, 2024, $$Product Design Lead$$, $$Led market research and product design for three rural banks, including seasonal loans repaid through off-takers and warehouse receipt financing, with financial modeling of costs and risk for each bank.$$, $$Two products piloted with 3,500 farmers; repayment above 95% in the first season.$$, $$[{"url":"https://picsum.photos/seed/demo-rowena-bautista-lacson-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rowena-bautista-lacson-portfolio-1-img1/900/600","caption":"Coffee aggregator interview in Bukidnon"},{"url":"https://picsum.photos/seed/demo-rowena-bautista-lacson-portfolio-1-img2/900/600","caption":"Product design workshop with rural bank staff"}]$$::jsonb, $$[{"url":"https://example.org/mindanao-value-chain-finance","label":"Pilot brief"}]$$::jsonb, NULL, 1),
  ('1bc059c8-5020-41d9-a8ff-5a40efe55423', '57e08d91-59a0-59d4-b146-bbd1d987a615', $$Agricultural Finance Market Assessment, Eastern Indonesia$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2019, 2020, $$Team Leader$$, $$Assessed demand and supply of agricultural credit and insurance across maize and seaweed value chains in Nusa Tenggara, including a 1,000-household survey.$$, $$Assessment shaped the agricultural finance component of an ADB rural development loan.$$, $$[{"url":"https://picsum.photos/seed/demo-rowena-bautista-lacson-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-rowena-bautista-lacson-portfolio-2-img1/900/600","caption":"Seaweed farmers in Nusa Tenggara"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('d6e00c72-c875-56b4-8223-d9c166b7d417', '57e08d91-59a0-59d4-b146-bbd1d987a615', $$Lending Policy Manual for a Rural Bank$$, $$Rural bank in Mindanao$$, NULL, 2011, 2012, $$Head of Agricultural Lending$$, $$Wrote the bank's lending policy manual for agricultural loans, including credit scoring for smallholders, collateral alternatives and portfolio limits by crop.$$, $$Agricultural portfolio grew by 60% over three years with stable repayment.$$, $$[{"url":"https://picsum.photos/seed/demo-rowena-bautista-lacson-lending-policy-manual-for-a-rural-bank-1/900/600","caption":"Loan officer training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('19e93f7a-9048-5f41-8803-db1d9d96955b', '57e08d91-59a0-59d4-b146-bbd1d987a615', $$Financial Literacy Radio Programme, Davao Region$$, $$Rural bank in Mindanao$$, NULL, 2013, 2014, $$Programme Designer$$, $$Designed a weekly radio programme in Cebuano on savings, loans and insurance for farming households, with call-in questions answered by loan officers.$$, $$Programme ran for two years; new savings accounts rose in the listening area.$$, $$[{"url":"https://picsum.photos/seed/demo-rowena-bautista-lacson-financial-literacy-radio-programme-davao-1/900/600","caption":"Radio studio recording"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('88f3e486-732e-5c43-9eb7-17d8738b8784', '57e08d91-59a0-59d4-b146-bbd1d987a615', $$8f84ca57-a860-4879-9ad0-d34f5e4f8159$$, NULL, $$Edgardo Villanueva$$, $$Bangko Sentral ng Pilipinas$$, $$Director, Inclusive Finance Advocacy$$, $$supervisor$$, $$evillanueva@bsp.gov.ph$$, (SELECT id FROM organizations WHERE name = $$Bangko Sentral ng Pilipinas$$), 2008, 2015, $$Agricultural lending at a rural bank in Mindanao$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Rowena's president at the rural bank in Mindanao before I joined the central bank. She built our agricultural lending from almost nothing into our strongest portfolio, with good repayment. She understands farmers and credit risk equally well. I would work with her again on agricultural finance.$$, $$auto$$, '2026-05-06T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-04T16:49:08.421Z'::timestamptz, '2026-05-06T16:34:44.421Z'::timestamptz, '2026-05-06T16:41:56.421Z'::timestamptz, '2026-05-06T16:49:08.421Z'::timestamptz, '2026-05-06T16:49:08.421Z'::timestamptz, '2026-05-07T16:49:08.421Z'::timestamptz, $$3a500f1ce7e7a8adad1a3acfcead1a60$$, '2026-05-03T16:49:08.421Z'::timestamptz);
