INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('e1ae4347-c50c-5ed9-989f-45001611c898', '57e08d91-59a0-59d4-b146-bbd1d987a615', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the value-chain finance products for coconut and coffee in Mindanao. I designed them with lenders and buyers. What changed is that farmers could borrow against buyer contracts instead of land titles.$$, 20),
  ('d53591d5-8ad4-5c66-a55e-067c6aa633d0', '57e08d91-59a0-59d4-b146-bbd1d987a615', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Eastern Indonesia I led a market assessment in a context new to me. I worked with local enumerators and village heads, and I learned how farmers there combine crops and credit.$$, 20),
  ('70064906-15b4-5908-a9d6-ceca3ecd2bd8', '57e08d91-59a0-59d4-b146-bbd1d987a615', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Once my analysis showed that a lender's flagship product was losing money. I explained the reasons with their own portfolio data and proposed changes they could make in three months.$$, 20),
  ('26b0ef46-f9f1-5861-8c82-4905659faca5', '57e08d91-59a0-59d4-b146-bbd1d987a615', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Filipino, English and Cebuano. Rural finance is about trust, so I always work through local banks and cooperatives that farmers already know.$$, 20),
  ('980ef5f3-d57c-509f-a4b1-a1af808b310a', '57e08d91-59a0-59d4-b146-bbd1d987a615', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in agricultural loan product design. It is not the right tool when the real problem is market access; then value-chain linkages come first.$$, 20);
