-- Ndèye Astou Faye
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('48394053-306f-42a6-be85-6a57b9ef7bf0', 'b183f7f7-ff54-5b98-acb7-c2055190df9c', $$GBV Referral Pathway Strengthening, Kolda and Sédhiou$$, $$UN Women$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2021, 2023, $$Programme Analyst$$, $$Mapped and strengthened referral pathways between health, police and justice services and trained frontline staff.$$, $$Referral times for survivors reduced; 400 frontline staff trained.$$, $$[{"url":"https://picsum.photos/seed/demo-ndeye-astou-faye-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-ndeye-astou-faye-portfolio-1-img1/900/600","caption":"Training of trainers in Kolda"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('7e4c7e7f-4c08-411e-9bb1-87ed2342ab79', 'b183f7f7-ff54-5b98-acb7-c2055190df9c', $$Gender Analysis for a Resilience Programme, Niger$$, $$Oxfam$$, (SELECT id FROM organizations WHERE name = $$Oxfam$$), 2019, 2019, $$Gender Consultant$$, $$Conducted qualitative research on women's roles in household resilience and drafted the programme's gender mainstreaming strategy.$$, $$Strategy adopted with women-specific targets for all programme components.$$, $$[{"url":"https://picsum.photos/seed/demo-ndeye-astou-faye-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-ndeye-astou-faye-portfolio-2-img1/900/600","caption":"Women's group discussion in Tillabéri"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('3b906a80-2347-5afe-987a-ed5c0a28e7cc', 'b183f7f7-ff54-5b98-acb7-c2055190df9c', $$Women's Legal Aid Clinics Evaluation, Senegal$$, $$UNFPA$$, (SELECT id FROM organizations WHERE name = $$UNFPA$$), 2024, 2024, $$Lead Evaluator$$, $$Evaluated four women's legal aid clinics run by a lawyers' association, through interviews with survivors, paralegals and police, and reviewed the referral links to psychosocial support.$$, $$Recommendations used to add psychosocial counsellors to two clinics.$$, $$[{"url":"https://picsum.photos/seed/demo-ndeye-astou-faye-women-s-legal-aid-clinics-evaluation-sen-1/900/600","caption":"Interview with paralegals in Thiès"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('0dbd9115-9ee3-574d-8489-ffd431565700', 'b183f7f7-ff54-5b98-acb7-c2055190df9c', $$b7d90d5f-f8c5-4b34-b5af-47a9c8aa178a$$, NULL, $$Aminata Diop$$, $$UN Women$$, $$Programme Specialist, Ending Violence Against Women$$, $$supervisor$$, $$aminata.diop@unwomen.org$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2019, 2024, $$GBV prevention and referral programmes in Senegal and Mali$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Ndèye Astou worked in my team for five years. She strengthened GBV referral pathways in Kolda and Sédhiou with real care for survivors, and her training of trainers reached hundreds of health, police and justice staff. She is committed and very effective. I would work with her again on GBV and women's rights programmes.$$, $$auto$$, '2026-07-20T16:49:08.421Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-18T16:49:08.421Z'::timestamptz, '2026-07-20T16:34:44.421Z'::timestamptz, '2026-07-20T16:41:56.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-21T16:49:08.421Z'::timestamptz, $$473d88c307818b4287b6b49021abefd3$$, '2026-07-17T16:49:08.421Z'::timestamptz);
