-- Cheikh Tidiane Sarr
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('64fe9da6-5ab9-424c-b706-32c1f8d441f6', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', $$E-Procurement Requirements and Architecture, Guinea$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2022, 2023, $$Lead Architect$$, $$Defined functional requirements for e-tendering, e-evaluation and supplier registration, and prepared the solution architecture with database management, hosting and interoperability with treasury systems.$$, $$Architecture adopted for the national e-procurement tender; platform went live in three pilot ministries.$$, $$[{"url":"https://picsum.photos/seed/demo-cheikh-tidiane-sarr-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-cheikh-tidiane-sarr-portfolio-1-img1/900/600","caption":"Requirements workshop with procurement officers"},{"url":"https://picsum.photos/seed/demo-cheikh-tidiane-sarr-portfolio-1-img2/900/600","caption":"Architecture review in Conakry"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('5006df80-e7c5-4197-9793-02b82f7c1e57', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', $$Government Interoperability Platform, Senegal$$, $$Agence de l'Informatique de l'État$$, NULL, 2014, 2017, $$Technical Director$$, $$Led the design and roll-out of the platform connecting treasury, tax, customs and procurement systems.$$, $$Twelve government systems connected; supplier tax clearance became automatic in procurement.$$, $$[{"url":"https://picsum.photos/seed/demo-cheikh-tidiane-sarr-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-cheikh-tidiane-sarr-portfolio-2-img1/900/600","caption":"Government data centre"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('0559d0f6-33b2-59dd-af72-a9110212c15d', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', $$National Broadband Strategy Review, Mauritania$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2021, $$Digital Infrastructure Consultant$$, $$Reviewed Mauritania's broadband strategy, backbone network and spectrum policy, and proposed measures to extend connectivity to secondary towns and public institutions.$$, $$Recommendations included in the government's digital economy programme.$$, $$[{"url":"https://picsum.photos/seed/demo-cheikh-tidiane-sarr-national-broadband-strategy-review-mauri-1/900/600","caption":"Backbone site visit"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('b06d3849-8f42-5498-9eb5-6bebd9b96c98', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', $$Digital Skills Programme for Civil Servants, Senegal$$, $$Agence de l'Informatique de l'État$$, NULL, 2016, 2017, $$Technical Director$$, $$Set up a digital skills programme for civil servants, from office tools to data protection and IT project management, delivered with the national school of administration.$$, $$3,000 civil servants trained in two years.$$, $$[{"url":"https://picsum.photos/seed/demo-cheikh-tidiane-sarr-digital-skills-programme-for-civil-serva-1/900/600","caption":"Training session in Dakar"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('40950803-0e53-590d-b9a3-cbcc1aa6b522', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', $$af9a39e3-818c-4d26-a78c-c1fc19c5c484$$, NULL, $$Mamadou Ba$$, $$World Bank$$, $$Senior Digital Development Specialist$$, $$supervisor$$, $$m.ba@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2010, 2018, $$Government IT at Senegal's state information technology agency$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Cheikh's director general at Senegal's state IT agency before I joined the World Bank. He ran our data centre, led the interoperability platform and launched the first e-procurement pilot. He is a rare architect who also understands public procurement rules. I would work with him again.$$, $$auto$$, '2026-06-25T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-23T16:49:08.421Z'::timestamptz, '2026-06-25T16:34:44.421Z'::timestamptz, '2026-06-25T16:41:56.421Z'::timestamptz, '2026-06-25T16:49:08.421Z'::timestamptz, '2026-06-25T16:49:08.421Z'::timestamptz, '2026-06-26T16:49:08.421Z'::timestamptz, $$7227120baffd7b2e73158753d5599c6e$$, '2026-06-22T16:49:08.421Z'::timestamptz);
