INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('d47b1e0c-5eda-53bc-a062-11027f0aec3e', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', NULL, '64fe9da6-5ab9-424c-b706-32c1f8d441f6', $$Fatoumata Kaba$$, $$World Bank$$, $$Senior Procurement Specialist$$, $$client$$, $$fkaba@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2022, 2023, $$E-procurement requirements and architecture for Guinea$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We contracted Cheikh to lead the e-procurement requirements and architecture for Guinea. His work was thorough and adapted to the country's capacity, and the platform went live in pilot ministries on his design.$$, $$auto$$, '2026-09-08T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-06T16:49:08.421Z'::timestamptz, '2026-09-08T16:34:44.421Z'::timestamptz, '2026-09-08T16:41:56.421Z'::timestamptz, '2026-09-08T16:49:08.421Z'::timestamptz, '2026-09-08T16:49:08.421Z'::timestamptz, '2026-09-09T16:49:08.421Z'::timestamptz, $$7ce751164b0113f6f2e664fd6677393f$$, '2026-09-05T16:49:08.421Z'::timestamptz);
