INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('d4c7a018-179d-5420-b0b0-79ec93656949', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of Senegal's government interoperability platform. I led its design and roll-out. What changed is that supplier tax clearance in procurement became automatic, and twelve government systems now share data.$$, 20),
  ('663dcc7a-8d3b-553d-a9fb-74e08082291f', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Guinea I worked on e-procurement in a different legal and technical context. I started by mapping the procurement process on paper with officers, before writing any requirements.$$, 20),
  ('a2db7e08-c8e1-5c95-ad87-71dcce24c858', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When a vendor's platform failed acceptance tests, I explained the failures to the client with evidence and a recovery plan, so the project stayed on track.$$, 20),
  ('b0035266-7308-53fd-b6a1-e2b08bd0557d', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in French, Wolof and English. In Francophone Africa I always involve national IT teams from the start, so that they can run the systems after we leave.$$, 20),
  ('48b423b2-5415-56bc-ad4d-59b5eb777f11', '7555a975-f2fe-5f78-9d7d-d8165e3dd015', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in solution architecture for government systems. It is not the right tool when processes are not yet agreed; then the work starts with process reform.$$, 20);
