-- Boureima Ouédraogo
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('3904c026-74c3-4a65-ac47-54630568f723', '241a438d-5451-528f-9d91-c26774ea5b18', $$E-Procurement Pilot and Supplier Registry, Burkina Faso$$, $$Agence Nationale de Promotion des TIC$$, NULL, 2016, 2018, $$Project Manager$$, $$Managed the e-procurement pilot and supplier registry, including requirements, vendor supervision, database migration and training of trainers for procurement officers.$$, $$Pilot ran 120 tenders online across three ministries.$$, $$[{"url":"https://picsum.photos/seed/demo-boureima-ouedraogo-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-boureima-ouedraogo-portfolio-1-img1/900/600","caption":"Training of procurement officers in Ouagadougou"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('2b2dd643-9d9b-4f53-ba81-18fd0b95f86c', '241a438d-5451-528f-9d91-c26774ea5b18', $$Treasury and Tax Interoperability Study, Niger$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2022, $$IT Consultant$$, $$Assessed interoperability between treasury, tax and procurement systems and recommended hosting on the national data centre or cloud services.$$, $$Recommendations included in the government's digital governance action plan.$$, $$[{"url":"https://picsum.photos/seed/demo-boureima-ouedraogo-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-boureima-ouedraogo-portfolio-2-img1/900/600","caption":"Systems mapping workshop in Niamey"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('fe396ed0-da96-5dbd-88ba-4b34e997082b', '241a438d-5451-528f-9d91-c26774ea5b18', $$Rural Telecentre Network Review, Burkina Faso$$, $$Agence Nationale de Promotion des TIC, Burkina Faso$$, NULL, 2014, 2015, $$Project Manager$$, $$Reviewed the sustainability of 40 rural telecentres, their connectivity costs and services, and proposed a management model with municipalities.$$, $$New management model adopted for 25 telecentres.$$, $$[{"url":"https://picsum.photos/seed/demo-boureima-ouedraogo-rural-telecentre-network-review-burkina--1/900/600","caption":"Telecentre visit near Koudougou"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('bd109c2a-4e32-50cb-89c0-a67b25b60f11', '241a438d-5451-528f-9d91-c26774ea5b18', $$c9aed388-aad8-4d4b-a654-752befa49c8c$$, NULL, $$Issouf Sawadogo$$, $$African Development Bank$$, $$Principal ICT Officer$$, $$supervisor$$, $$i.sawadogo@afdb.org$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2013, 2019, $$Digital government projects at Burkina Faso's ICT promotion agency$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Boureima at Burkina Faso's ICT promotion agency before joining the African Development Bank. He managed the e-procurement pilot and the supplier registry, and kept projects moving with limited resources. He is reliable and pragmatic. I would work with him again on digital government projects.$$, $$auto$$, '2026-06-15T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-13T16:49:08.421Z'::timestamptz, '2026-06-15T16:34:44.421Z'::timestamptz, '2026-06-15T16:41:56.421Z'::timestamptz, '2026-06-15T16:49:08.421Z'::timestamptz, '2026-06-15T16:49:08.421Z'::timestamptz, '2026-06-16T16:49:08.421Z'::timestamptz, $$20d6e8243ecdee2f27bbc91226737084$$, '2026-06-12T16:49:08.421Z'::timestamptz);
