-- Aminata Koné-Traoré
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('edd96a91-6b2e-5266-9b0b-1a00ebeda018', '25817ced-5288-5fe9-8eb1-463c136bf4ac', $$National E-Procurement Platform Roll-out, Côte d'Ivoire$$, $$Direction des Marchés Publics, Côte d'Ivoire$$, NULL, 2016, 2021, $$Head of E-Procurement Unit$$, $$Led the national e-procurement programme from requirements to go-live: functional requirements for e-tendering, e-evaluation and e-contract management, procurement of the platform vendor, supplier registry design, and interoperability with treasury and tax systems. Ran the change management programme for procurement officers and suppliers, including a training of trainers network in every region.$$, $$All central ministries tendering online by 2020; average tender cycle cut from 94 to 51 days; 6,000 suppliers registered.$$, $$[{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-national-e-procurement-platform-roll-out-1/900/600","caption":"Go-live in the Ministry of Health"},{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-national-e-procurement-platform-roll-out-2/900/600","caption":"Regional training of trainers"},{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-national-e-procurement-platform-roll-out-3/900/600","caption":"Supplier help desk"}]$$::jsonb, $$[{"label":"Programme overview","url":"https://example.org/demo/ci-eprocurement"}]$$::jsonb, NULL, 1),
  ('108ffc58-b51a-54e3-bb71-676b95448095', '25817ced-5288-5fe9-8eb1-463c136bf4ac', $$E-Procurement Readiness Assessment, Togo$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2022, 2022, $$Lead Specialist$$, $$Assessed Togo's legal framework, institutional capacity and IT infrastructure for e-procurement using the MAPS e-procurement module, and prepared a phased roadmap with costed options for hosting and interoperability.$$, $$Roadmap adopted by the procurement regulator; first phase financed under a new World Bank operation.$$, $$[{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-e-procurement-readiness-assessment-togo-1/900/600","caption":"Validation workshop in Lomé"},{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-e-procurement-readiness-assessment-togo-2/900/600","caption":"Readiness scorecard"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('ece512a5-0e33-5860-bfcb-5a69e79a6ae3', '25817ced-5288-5fe9-8eb1-463c136bf4ac', $$Open Contracting Data Publication, Senegal$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2023, 2024, $$E-Procurement Specialist$$, $$Advised Senegal's procurement directorate on publishing contracting data in the Open Contracting Data Standard from its e-procurement system, including data quality checks and red-flag indicators for the integrity agency.$$, $$Monthly OCDS releases since 2024; red-flag dashboard used by the integrity agency in two audits.$$, $$[{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-open-contracting-data-publication-senega-1/900/600","caption":"Data quality review session"},{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-open-contracting-data-publication-senega-2/900/600","caption":"Red-flag dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('6e2602d4-e2ad-5c7a-b7cb-7647fa30f473', '25817ced-5288-5fe9-8eb1-463c136bf4ac', $$Procurement Officer Certification Programme, Guinea$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2024, NULL, $$Programme Designer$$, $$Designing a certification path for public procurement officers in Guinea, with modules on e-tendering and contract management delivered by national trainers.$$, $$First cohort of 40 officers enrolled; national trainers delivering two of five modules.$$, $$[{"url":"https://picsum.photos/seed/demo-aminata-kone-traore-procurement-officer-certification-progra-1/900/600","caption":"Trainer preparation in Conakry"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('4400f91f-6a19-5c23-b040-9b210784019d', '25817ced-5288-5fe9-8eb1-463c136bf4ac', $$60adaef5-9c2a-54c5-879b-612a86e9da31$$, NULL, $$Mamadou Lamine Diallo$$, $$World Bank$$, $$Senior Procurement Specialist$$, $$supervisor$$, $$m.l.diallo@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2024, $$E-procurement support to Togo, Senegal and Guinea$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Aminata on our e-procurement work in Togo, Senegal and Guinea. What she brings is rare: she has actually run a national platform, so governments listen to her. In Togo her readiness assessment was the clearest I have seen, and the regulator adopted the roadmap almost unchanged. In Senegal she got the open contracting data published every month, which many teams promise and few deliver. I would work with her again on any procurement digitisation assignment, especially where officials are nervous about moving from paper.$$, $$auto$$, '2026-09-13T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-11T16:49:08.421Z'::timestamptz, '2026-09-13T16:34:44.421Z'::timestamptz, '2026-09-13T16:41:56.421Z'::timestamptz, '2026-09-13T16:49:08.421Z'::timestamptz, '2026-09-13T16:49:08.421Z'::timestamptz, '2026-09-14T16:49:08.421Z'::timestamptz, $$222ddf9ef5e0586e314aacbbf59a8261$$, '2026-09-10T16:49:08.421Z'::timestamptz);
