INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('a3585254-322a-5471-958d-f7f682d12b76', '25817ced-5288-5fe9-8eb1-463c136bf4ac', NULL, 'edd96a91-6b2e-5266-9b0b-1a00ebeda018', $$Koffi Désiré Yapo$$, $$World Bank$$, $$Digital Development Specialist$$, $$supervisor$$, $$kd.yapo@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2016, 2021, $$National e-procurement platform roll-out$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Aminata's director during the national e-procurement roll-out. She led the unit that wrote the requirements, managed the vendor, and trained officers in every region. When the go-live in the first ministries ran into supplier registration problems, she set up a help desk in a week and kept the timetable. She is calm under pressure and very organised. I would work with her again on platform roll-outs and on change management with procurement officers.$$, $$auto$$, '2026-09-15T16:49:08.421Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-13T16:49:08.421Z'::timestamptz, '2026-09-15T16:34:44.421Z'::timestamptz, '2026-09-15T16:41:56.421Z'::timestamptz, '2026-09-15T16:49:08.421Z'::timestamptz, '2026-09-15T16:49:08.421Z'::timestamptz, '2026-09-16T16:49:08.421Z'::timestamptz, $$e4cbcbb4209989a4c760afbaf7bdc381$$, '2026-09-12T16:49:08.421Z'::timestamptz);
