-- Ousmane Ndiaye Fall
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('7c1fca38-7223-5600-929f-6f8662c77d6d', 'c4dc5ea7-bbe7-5128-b3a2-189cbc5487ef', $$E-Tendering and E-Evaluation Modules, Senegal$$, $$Agence de l'Informatique de l'État, Senegal$$, NULL, 2018, 2022, $$Product Manager$$, $$Owned the backlog for the e-tendering and e-evaluation modules of the national e-procurement platform. Ran user research with procurement officers and suppliers, wrote user stories for the vendor, led acceptance testing, and coordinated the change management plan for pilot ministries.$$, $$Modules live in eight ministries; online bid submission rose from 0 to 72% of tenders in two years.$$, $$[{"url":"https://picsum.photos/seed/demo-ousmane-ndiaye-fall-e-tendering-and-e-evaluation-modules-sen-1/900/600","caption":"User testing with procurement officers"},{"url":"https://picsum.photos/seed/demo-ousmane-ndiaye-fall-e-tendering-and-e-evaluation-modules-sen-2/900/600","caption":"Sprint review with the vendor"},{"url":"https://picsum.photos/seed/demo-ousmane-ndiaye-fall-e-tendering-and-e-evaluation-modules-sen-3/900/600","caption":"Pilot ministry go-live"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('422d44e2-aad7-53e6-a814-dd63b66f56cb', 'c4dc5ea7-bbe7-5128-b3a2-189cbc5487ef', $$Online Services on Shared Digital Infrastructure, Senegal$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, NULL, $$Digital Transformation Specialist$$, $$Supporting three ministries to redesign services (licences, certificates and grant applications) as online services using the national identity, e-payment and document exchange components.$$, $$Two services launched; average completion time for a professional licence fell from three weeks to four days.$$, $$[{"url":"https://picsum.photos/seed/demo-ousmane-ndiaye-fall-online-services-on-shared-digital-infras-1/900/600","caption":"Service design workshop"},{"url":"https://picsum.photos/seed/demo-ousmane-ndiaye-fall-online-services-on-shared-digital-infras-2/900/600","caption":"Prototype testing at a citizen service centre"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('031d45cd-0c16-5c12-a7f7-2562c9ff3634', 'c4dc5ea7-bbe7-5128-b3a2-189cbc5487ef', $$Product Owner Training for Civil Servants$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2023, 2024, $$Trainer and Course Designer$$, $$Designed and delivered a six-week course for civil servants who act as product owners on government IT projects: user research, backlog writing, vendor management and acceptance testing.$$, $$48 civil servants trained across 12 agencies; course now run by the national school of administration.$$, $$[{"url":"https://picsum.photos/seed/demo-ousmane-ndiaye-fall-product-owner-training-for-civil-servant-1/900/600","caption":"Course session in Dakar"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('2b1b5be6-a20c-5990-b372-0218128ff68f', 'c4dc5ea7-bbe7-5128-b3a2-189cbc5487ef', $$ffee9088-7066-53bf-b5f8-07956fbef164$$, NULL, $$Awa Diop Sène$$, $$UNDP$$, $$Head of Governance Unit$$, $$supervisor$$, $$awa.sene@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2025, $$Digital transformation support to Senegalese ministries$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Ousmane has worked in my unit for three years on digital transformation with Senegalese ministries. He listens to civil servants first, then turns what he hears into something a vendor can build. The professional licence service he led cut processing time from weeks to days, and the ministry now runs it without us. He is also a good trainer; the product owner course he designed has been taken over by the national school of administration. I would work with him again on any government service design or e-procurement product work.$$, $$auto$$, '2026-08-29T16:49:08.421Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-27T16:49:08.421Z'::timestamptz, '2026-08-29T16:34:44.421Z'::timestamptz, '2026-08-29T16:41:56.421Z'::timestamptz, '2026-08-29T16:49:08.421Z'::timestamptz, '2026-08-29T16:49:08.421Z'::timestamptz, '2026-08-30T16:49:08.421Z'::timestamptz, $$8be3636c2b2af18bffd7adfaa7b4a276$$, '2026-08-26T16:49:08.421Z'::timestamptz);
