-- Claire Mbarga Lefèvre
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('665a382a-80c8-56fa-aeb6-d56aa1eeabe5', '4d62bc95-42dc-5dc7-a18a-21341b7dbc80', $$E-Procurement Functional Requirements, Benin$$, $$Crown Agents$$, (SELECT id FROM organizations WHERE name = $$Crown Agents$$), 2020, 2021, $$Lead Procurement Systems Adviser$$, $$Defined functional requirements for e-tendering, e-evaluation, e-contract management and the supplier registry, aligned with Benin's procurement code, and drafted the regulatory amendments needed to give electronic bids legal force.$$, $$Requirements used to procure the national platform; regulatory amendments adopted in 2021.$$, $$[{"url":"https://picsum.photos/seed/demo-claire-mbarga-lefevre-e-procurement-functional-requirements-be-1/900/600","caption":"Requirements validation workshop in Cotonou"},{"url":"https://picsum.photos/seed/demo-claire-mbarga-lefevre-e-procurement-functional-requirements-be-2/900/600","caption":"Process mapping with procurement officers"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('0aabc7da-671e-5235-8f55-5a3d28957cfb', '4d62bc95-42dc-5dc7-a18a-21341b7dbc80', $$Supplier Registry and Bid-Rigging Indicators, DRC$$, $$Crown Agents$$, (SELECT id FROM organizations WHERE name = $$Crown Agents$$), 2022, 2023, $$Procurement Systems Adviser$$, $$Designed a national supplier registry and a set of collusion and bid-rigging indicators drawn from procurement records, and trained the integrity agency's analysts to use them.$$, $$Registry live for central government; indicators flagged 23 tenders for review in the first year.$$, $$[{"url":"https://picsum.photos/seed/demo-claire-mbarga-lefevre-supplier-registry-and-bid-rigging-indica-1/900/600","caption":"Analyst training in Kinshasa"},{"url":"https://picsum.photos/seed/demo-claire-mbarga-lefevre-supplier-registry-and-bid-rigging-indica-2/900/600","caption":"Indicator dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('aac2f282-c81e-5bba-9f83-b2191b380941', '4d62bc95-42dc-5dc7-a18a-21341b7dbc80', $$MAPS Assessment, Cameroon$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2017, 2018, $$Procurement Specialist$$, $$Co-led the MAPS assessment of Cameroon's public procurement system, covering the legal framework, institutions, operations and integrity, with a dedicated review of readiness for e-procurement.$$, $$Assessment validated by government and partners; action plan used to prioritise reforms.$$, $$[{"url":"https://picsum.photos/seed/demo-claire-mbarga-lefevre-maps-assessment-cameroon-1/900/600","caption":"Validation meeting in Yaoundé"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6ccad16f-5273-581b-a0e0-e3d3f2736f65', '4d62bc95-42dc-5dc7-a18a-21341b7dbc80', $$b03ab6c2-8d1c-5615-bc68-efab63186b73$$, NULL, $$Jonathan Price-Okeke$$, $$Crown Agents$$, $$Director, Public Financial Management$$, $$supervisor$$, $$j.price-okeke@crownagents.com$$, (SELECT id FROM organizations WHERE name = $$Crown Agents$$), 2019, 2025, $$Procurement reform programmes in Benin and the DRC$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I have managed Claire at Crown Agents for six years. She knows procurement law in Francophone Africa better than anyone on my team, and she can translate it into requirements an IT vendor understands. In Benin she wrote both the platform requirements and the regulatory amendments, which saved the government a year. In the DRC her bid-rigging indicators gave the integrity agency its first real cases. I would work with her again on any e-procurement or procurement integrity assignment.$$, $$auto$$, '2026-08-14T16:49:08.421Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-12T16:49:08.421Z'::timestamptz, '2026-08-14T16:34:44.421Z'::timestamptz, '2026-08-14T16:41:56.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-14T16:49:08.421Z'::timestamptz, '2026-08-15T16:49:08.421Z'::timestamptz, $$0c15e362aee760ae290994fcda61a16f$$, '2026-08-11T16:49:08.421Z'::timestamptz);
