-- Yao Kouassi N'Guessan
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('620bf866-13dc-51ef-9129-292dfccf2a49', 'c6a4ec71-4ab4-533e-a810-a00822add5e1', $$Online Business Permit Platform, Côte d'Ivoire$$, $$Centre de Promotion des Investissements en Côte d'Ivoire$$, NULL, 2022, 2023, $$Lead Developer$$, $$Designed and built a web platform for online business permit applications, including the database design, integration with the tax identification system, and hosting in the government data centre. Wrote the administrator manual and trained the agency's IT team to run and update the platform.$$, $$Average permit processing time fell from 21 to 6 days; 9,000 applications were filed online in the first year.$$, $$[{"url":"https://picsum.photos/seed/demo-yao-kouassi-nguessan-online-business-permit-platform-cote-d-i-1/900/600","caption":"Platform training for permit officers"},{"url":"https://picsum.photos/seed/demo-yao-kouassi-nguessan-online-business-permit-platform-cote-d-i-2/900/600","caption":"Database migration workshop"},{"url":"https://picsum.photos/seed/demo-yao-kouassi-nguessan-online-business-permit-platform-cote-d-i-3/900/600","caption":"Service performance dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('fbd6ab4c-1d24-599a-ac10-4a2a83f9563e', 'c6a4ec71-4ab4-533e-a810-a00822add5e1', $$Supplier Registry Module, National Procurement Portal$$, $$Direction des Marchés Publics, Côte d'Ivoire$$, NULL, 2021, 2022, $$Database Developer$$, $$Built the supplier registry module for the national procurement portal: supplier accounts, document upload, tax and social security clearance checks through the government interoperability layer, and an admin console for procurement officers.$$, $$Over 4,000 suppliers registered in the first six months; clearance checks that took a week now run automatically.$$, $$[{"url":"https://picsum.photos/seed/demo-yao-kouassi-nguessan-supplier-registry-module-national-procur-1/900/600","caption":"Supplier registration screen"},{"url":"https://picsum.photos/seed/demo-yao-kouassi-nguessan-supplier-registry-module-national-procur-2/900/600","caption":"Testing session with procurement officers"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('36501e43-16c0-5111-8a24-292dd30ff49a', 'c6a4ec71-4ab4-533e-a810-a00822add5e1', $$Civil Registry Digitisation, Burkina Faso$$, $$UNICEF$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2019, 2020, $$Systems Developer$$, $$Developed the database and data-entry application used to digitise birth records in four regions, with offline capture for health centres and nightly synchronisation to the national server.$$, $$310,000 records digitised; duplicate records fell by two thirds after the matching rules went live.$$, $$[{"url":"https://picsum.photos/seed/demo-yao-kouassi-nguessan-civil-registry-digitisation-burkina-faso-1/900/600","caption":"Offline data-entry tablets"},{"url":"https://picsum.photos/seed/demo-yao-kouassi-nguessan-civil-registry-digitisation-burkina-faso-2/900/600","caption":"Training for registry clerks"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('dd26aa9e-7831-5ae5-adad-5782843ef1cf', 'c6a4ec71-4ab4-533e-a810-a00822add5e1', $$7afd34c6-d2e9-5131-ba93-9c4ec3a3ba9b$$, NULL, $$Fatou Bintou Camara$$, $$African Development Bank$$, $$Chief Information Systems Officer$$, $$supervisor$$, $$f.camara@afdb.org$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2017, 2020, $$Reporting databases and web applications for country operations$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Yao worked in my team for three years building reporting databases and web applications for our country offices. He writes clean, well-documented code and he always thinks about who will maintain the system after he leaves. When one of our reporting tools failed before a board deadline, he rebuilt the data pipeline over a weekend and documented it so the team could run it. I would work with him again on database and web platform projects for public institutions.$$, $$auto$$, '2026-06-25T16:49:08.421Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-23T16:49:08.421Z'::timestamptz, '2026-06-25T16:34:44.421Z'::timestamptz, '2026-06-25T16:41:56.421Z'::timestamptz, '2026-06-25T16:49:08.421Z'::timestamptz, '2026-06-25T16:49:08.421Z'::timestamptz, '2026-06-26T16:49:08.421Z'::timestamptz, $$ddf7016885c659e29d7d5217eaa0306b$$, '2026-06-22T16:49:08.421Z'::timestamptz);
