  ('52215307-ca3e-55f9-bcb2-2de4f3abd475', '15e4bfa0-74a2-5d30-b10f-6cc5a2934d3b', $$Supplier Registry Module, National Procurement Portal$$, $$Direction des Marchés Publics, Côte d'Ivoire$$, NULL, 2021, 2022, $$Database Developer$$, $$Built the supplier registry module for the national procurement portal: supplier accounts, document upload, tax and social security clearance checks through the government interoperability layer, and an admin console for procurement officers.$$, $$Over 4,000 suppliers registered in the first six months; clearance checks that took a week now run automatically.$$, $$[{"url":"https://picsum.photos/seed/demo-serge-kouame-ndri-supplier-registry-module-national-procur-1/900/600","caption":"Supplier registration screen"},{"url":"https://picsum.photos/seed/demo-serge-kouame-ndri-supplier-registry-module-national-procur-2/900/600","caption":"Testing session with procurement officers"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('6ebccf0b-0ba8-593b-a4ff-3ecc866d6e86', '15e4bfa0-74a2-5d30-b10f-6cc5a2934d3b', $$Civil Registry Digitisation, Burkina Faso$$, $$UNICEF$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2019, 2020, $$Systems Developer$$, $$Developed the database and data-entry application used to digitise birth records in four regions, with offline capture for health centres and nightly synchronisation to the national server.$$, $$310,000 records digitised; duplicate records fell by two thirds after the matching rules went live.$$, $$[{"url":"https://picsum.photos/seed/demo-serge-kouame-ndri-civil-registry-digitisation-burkina-faso-1/900/600","caption":"Offline data-entry tablets"},{"url":"https://picsum.photos/seed/demo-serge-kouame-ndri-civil-registry-digitisation-burkina-faso-2/900/600","caption":"Training for registry clerks"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('4f889ce8-7f90-5f2a-baea-43627447231e', '15e4bfa0-74a2-5d30-b10f-6cc5a2934d3b', $$eb93169f-a8db-5dfa-a73b-323c6ef37d82$$, NULL, $$Émile Konan Assi$$, $$UNDP$$, $$Operations Manager$$, $$supervisor$$, $$emile.assi@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2017, 2020, $$Web applications and reporting databases for the country office$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Serge worked with me for three years on the country office's web applications and reporting databases. He is reliable and methodical: requirements written down, tests before release, and a handover note for every system. He trained our administrative staff to manage user accounts themselves, which cut our support requests in half. I would work with him again on information systems for government partners.$$, $$auto$$, '2026-07-20T16:49:08.421Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-18T16:49:08.421Z'::timestamptz, '2026-07-20T16:34:44.421Z'::timestamptz, '2026-07-20T16:41:56.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-20T16:49:08.421Z'::timestamptz, '2026-07-21T16:49:08.421Z'::timestamptz, $$e2706469c0e81d23f90def9de96c8c38$$, '2026-07-17T16:49:08.421Z'::timestamptz);
