-- Mariam Coulibaly-Sanogo
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('347708df-2a87-58a0-bec5-c1241e9e95b4', '3f607f18-d9aa-58c7-b7bf-97b919ff8764', $$Treasury and E-Procurement Interface, Côte d'Ivoire$$, $$Direction Générale du Trésor et de la Comptabilité Publique, Côte d'Ivoire$$, NULL, 2017, 2020, $$Head, Budget Execution Systems$$, $$Led the integration between the treasury's budget commitment controls and the national e-procurement platform, so that contracts awarded online reserve funds automatically and payments match contract milestones. Coordinated the data exchange with the tax administration for automatic supplier tax clearance through the government interoperability layer.$$, $$Contracts signed without reserved funds fell to almost zero; supplier payment arrears down 30% in two years.$$, $$[{"url":"https://picsum.photos/seed/demo-mariam-coulibaly-sanogo-treasury-and-e-procurement-interface-cot-1/900/600","caption":"Interface testing with the e-procurement team"},{"url":"https://picsum.photos/seed/demo-mariam-coulibaly-sanogo-treasury-and-e-procurement-interface-cot-2/900/600","caption":"Treasury systems team"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('ebaaa736-97cd-5157-885b-f4b42a4adaa7', '3f607f18-d9aa-58c7-b7bf-97b919ff8764', $$Digital Invoicing for Government Suppliers, WAEMU$$, $$African Development Bank$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2022, 2024, $$PFM Consultant$$, $$Designed the approach for electronic invoices from government suppliers in two WAEMU countries, linking supplier records in the e-procurement systems to treasury payment processing and digital public services for document exchange.$$, $$Pilot live in one country; invoice processing time fell from 45 to 12 days for pilot ministries.$$, $$[{"url":"https://picsum.photos/seed/demo-mariam-coulibaly-sanogo-digital-invoicing-for-government-supplie-1/900/600","caption":"Supplier consultation in Dakar"},{"url":"https://picsum.photos/seed/demo-mariam-coulibaly-sanogo-digital-invoicing-for-government-supplie-2/900/600","caption":"Invoice workflow mapping"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('296dfb90-640c-5bd4-a1cd-11af04343dc9', '3f607f18-d9aa-58c7-b7bf-97b919ff8764', $$IFMIS Review and Results Indicators, Togo$$, $$African Development Bank$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2021, 2021, $$Lead Reviewer$$, $$Reviewed Togo's integrated financial management information system, its controls and its links to procurement, and designed disbursement-linked indicators for a results-based treasury reform programme.$$, $$Five indicators adopted; first two tranches disbursed on verified results.$$, $$[{"url":"https://picsum.photos/seed/demo-mariam-coulibaly-sanogo-ifmis-review-and-results-indicators-togo-1/900/600","caption":"Review mission in Lomé"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6b00dff8-92c9-5d5d-941c-ea493512212c', '3f607f18-d9aa-58c7-b7bf-97b919ff8764', $$3bcaa10f-ff95-5573-bb21-09e7d7029c45$$, NULL, $$Hervé N'Goran Kacou$$, $$African Development Bank$$, $$Principal Public Financial Management Officer$$, $$supervisor$$, $$h.kacou@afdb.org$$, (SELECT id FROM organizations WHERE name = $$African Development Bank$$), 2020, 2025, $$PFM and digital invoicing assignments in WAEMU countries$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Mariam has been our lead PFM consultant on several West African operations since 2020. She knows treasury systems from the inside, which shows when she talks to ministry teams. The digital invoicing pilot she designed connects procurement, treasury and suppliers in a way that actually works on the ground. Her reports are precise and ready to use. I would work with her again on treasury reform, IFMIS and any work at the boundary between procurement and payments.$$, $$auto$$, '2026-08-24T16:49:08.421Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-22T16:49:08.421Z'::timestamptz, '2026-08-24T16:34:44.421Z'::timestamptz, '2026-08-24T16:41:56.421Z'::timestamptz, '2026-08-24T16:49:08.421Z'::timestamptz, '2026-08-24T16:49:08.421Z'::timestamptz, '2026-08-25T16:49:08.421Z'::timestamptz, $$9e3662d5e93a57572ce0228deef533ed$$, '2026-08-21T16:49:08.421Z'::timestamptz);
